//! Tables of the IFC schemas (ADR-0018): entities with their supertype, abstract flag, explicit,
//! derived and inverse attributes, `UNIQUE` and `WHERE` rules; defined, enumeration and select
//! types; functions and global rules. The tables are data generated by `cargo xtask ifc-schema`
//! from the published EXPRESS schemas; no Rust type exists per entity.
//!
//! Every table is sorted by the upper-case name, so a lookup is a binary search that ignores ASCII
//! case and finds a name as a STEP file writes it. Cross references are indexes into the tables of
//! the same schema.
//!
//! Only the IFC4X3 file is part of the repository (published under CC BY-ND 4.0, ADR-0018). The
//! IFC2X3 and IFC4 files are generated locally; the build script enables each schema when its file
//! is present in `src/schema/generated/`, and [`SchemaTables::of`] returns `None` for a schema
//! without one.

use std::cmp::Ordering;

use crate::model::Schema;

pub(crate) mod access;
mod check;
mod eval;
mod inverse;
mod level3;
pub mod tree;

pub use access::Typed;
pub use check::{Conformance, Finding, RuleCount};
pub use inverse::{InverseIndex, Referrer};
pub use level3::{RuleScope, WhereCount};
use tree::{Algorithm, Expr};

#[cfg(any(arc_ifc_tables_ifc2x3, arc_ifc_tables_ifc4, arc_ifc_tables_ifc4x3))]
mod generated {
    #[allow(unused_imports)]
    use super::tree::{
        Algorithm, BinaryOp, Branch, Builtin, Element, Expr, Increment, Local, Logical, Stmt,
        UnaryOp,
    };
    #[allow(unused_imports)]
    use super::{
        Aggregate, AggregateKind, Attribute, AttributeRef, Bound, DefinedType, Derived, Entity,
        Enumeration, Function, GlobalRule, Inverse, InverseAggregate, Named, SchemaTables, Select,
        TypeRef, UniqueRule, WhereRule,
    };
    #[cfg(arc_ifc_tables_ifc2x3)]
    include!("generated/ifc2x3.rs");
    #[cfg(arc_ifc_tables_ifc4)]
    include!("generated/ifc4.rs");
    #[cfg(arc_ifc_tables_ifc4x3)]
    include!("generated/ifc4x3.rs");
}

/// The tables of one schema.
#[derive(Debug)]
pub struct SchemaTables {
    /// The schema name of the source, such as `IFC4X3_ADD2`.
    pub name: &'static str,
    /// The BLAKE3 digest (hexadecimal) of the EXPRESS source the tables were generated from.
    pub source_blake3: &'static str,
    /// Entities by upper-case name.
    pub entities: &'static [Entity],
    /// Defined types by upper-case name.
    pub defined_types: &'static [DefinedType],
    /// Enumeration types by upper-case name.
    pub enumerations: &'static [Enumeration],
    /// Select types by upper-case name.
    pub selects: &'static [Select],
    /// Functions by upper-case name.
    pub functions: &'static [Function],
    /// Global rules by upper-case name.
    pub rules: &'static [GlobalRule],
}

/// An entity declaration.
#[derive(Debug)]
pub struct Entity {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// Index of the supertype in [`SchemaTables::entities`].
    pub supertype: Option<u16>,
    /// Whether instances of the entity alone are refused (`ABSTRACT`).
    pub is_abstract: bool,
    /// The direct subtypes listed in `SUPERTYPE OF (ONEOF (...))`, of which an instance is at most
    /// one.
    pub one_of: &'static [u16],
    /// The explicit attributes declared here, in order; inherited ones come first in a record.
    pub attributes: &'static [Attribute],
    /// The derived attributes declared here.
    pub derived: &'static [Derived],
    /// The inverse attributes declared here.
    pub inverses: &'static [Inverse],
    /// The uniqueness rules.
    pub unique: &'static [UniqueRule],
    /// The domain rules.
    pub where_rules: &'static [WhereRule],
}

/// An explicit attribute.
#[derive(Debug)]
pub struct Attribute {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The value type.
    pub ty: TypeRef,
    /// Whether the value may be omitted (`$`).
    pub optional: bool,
}

/// An explicit attribute of an entity: the entity index and the position in its
/// [`Entity::attributes`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AttributeRef {
    /// The declaring entity.
    pub entity: u16,
    /// The position among the attributes the entity declares.
    pub index: u16,
}

/// A derived attribute.
#[derive(Debug)]
pub struct Derived {
    /// The name; for a re-declaration the name of the inherited attribute.
    pub name: &'static str,
    /// The inherited explicit attribute this one re-declares as derived; a record writes `*` in
    /// its position.
    pub redeclares: Option<AttributeRef>,
    /// The value type.
    pub ty: TypeRef,
    /// The expression as written in the schema.
    pub source: &'static str,
    /// The parsed expression, evaluated with `SELF` the instance.
    pub tree: Expr,
}

/// An inverse attribute.
#[derive(Debug)]
pub struct Inverse {
    /// The name.
    pub name: &'static str,
    /// The entity whose attribute refers to this one.
    pub entity: u16,
    /// The name of that attribute.
    pub attribute: &'static str,
    /// `SET` or `BAG` with bounds; `None` when exactly one instance refers.
    pub aggregate: Option<InverseAggregate>,
}

/// The aggregation of an inverse attribute.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InverseAggregate {
    /// `Set` or `Bag`.
    pub kind: AggregateKind,
    /// The smallest number of referring instances.
    pub lower: Bound,
    /// The largest number of referring instances.
    pub upper: Bound,
}

/// A `UNIQUE` rule.
#[derive(Debug)]
pub struct UniqueRule {
    /// The label, such as `UR1`.
    pub label: Option<&'static str>,
    /// The attributes whose combined values are unique, as written (`Name` or `SELF\Entity.Name`).
    pub attributes: &'static [&'static str],
}

/// A `WHERE` rule of an entity, a defined type or a global rule.
#[derive(Debug)]
pub struct WhereRule {
    /// The label, such as `WR1`.
    pub label: Option<&'static str>,
    /// The expression as written in the schema.
    pub source: &'static str,
    /// The parsed expression.
    pub tree: Expr,
}

/// A defined type (`TYPE IfcLabel = STRING;`).
#[derive(Debug)]
pub struct DefinedType {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The underlying type.
    pub underlying: TypeRef,
    /// The domain rules.
    pub where_rules: &'static [WhereRule],
}

/// An enumeration type.
#[derive(Debug)]
pub struct Enumeration {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The items in declared order, as the schema writes them.
    pub items: &'static [&'static str],
}

impl Enumeration {
    /// Whether `item` is an item of the enumeration, ignoring ASCII case.
    #[must_use]
    pub fn contains(&self, item: &str) -> bool {
        self.items.iter().any(|i| i.eq_ignore_ascii_case(item))
    }
}

/// A select type.
#[derive(Debug)]
pub struct Select {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The member types in declared order.
    pub members: &'static [Named],
}

/// A function.
#[derive(Debug)]
pub struct Function {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The declaration as written, from `FUNCTION` to `END_FUNCTION;`.
    pub source: &'static str,
    /// The parsed parameters, locals and body.
    pub tree: Algorithm,
}

/// A global rule.
#[derive(Debug)]
pub struct GlobalRule {
    /// The name as the schema writes it.
    pub name: &'static str,
    /// The entities the rule ranges over.
    pub entities: &'static [u16],
    /// The domain rules of the rule.
    pub where_rules: &'static [WhereRule],
    /// The declaration as written, from `RULE` to `END_RULE;`.
    pub source: &'static str,
    /// The parsed locals and body; the domain rules read its variables.
    pub tree: Algorithm,
}

/// A named type: an index into one of the tables.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Named {
    /// [`SchemaTables::entities`].
    Entity(u16),
    /// [`SchemaTables::defined_types`].
    Defined(u16),
    /// [`SchemaTables::enumerations`].
    Enumeration(u16),
    /// [`SchemaTables::selects`].
    Select(u16),
}

/// The type of an attribute or the underlying type of a defined type.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TypeRef {
    /// `INTEGER`.
    Integer,
    /// `REAL`.
    Real,
    /// `NUMBER`.
    Number,
    /// `BOOLEAN`.
    Boolean,
    /// `LOGICAL`.
    Logical,
    /// `STRING [(width) [FIXED]]`.
    String {
        /// The maximum or, with `fixed`, exact length.
        width: Option<u32>,
        /// Whether the width is exact.
        fixed: bool,
    },
    /// `BINARY [(width) [FIXED]]`.
    Binary {
        /// The maximum or, with `fixed`, exact number of bits.
        width: Option<u32>,
        /// Whether the width is exact.
        fixed: bool,
    },
    /// A named type.
    Named(Named),
    /// An aggregate.
    Aggregate(&'static Aggregate),
}

/// An aggregation type.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AggregateKind {
    /// `ARRAY`: fixed index range.
    Array,
    /// `LIST`: ordered.
    List,
    /// `SET`: unordered, no repeats.
    Set,
    /// `BAG`: unordered.
    Bag,
}

/// A bound of an aggregate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Bound {
    /// A literal value.
    Value(u32),
    /// `?`: no upper bound.
    Unbounded,
    /// An expression over other attributes, as written.
    Expression(&'static str),
}

/// An aggregate type.
#[derive(Debug, PartialEq, Eq)]
pub struct Aggregate {
    /// The aggregation.
    pub kind: AggregateKind,
    /// The lower bound (index for arrays, size otherwise).
    pub lower: Bound,
    /// The upper bound.
    pub upper: Bound,
    /// `ARRAY OF OPTIONAL`: elements may be missing.
    pub optional: bool,
    /// `UNIQUE`: no element occurs twice.
    pub unique: bool,
    /// The element type.
    pub element: TypeRef,
}

/// One position of a record: an explicit attribute of the entity or a supertype.
#[derive(Clone, Copy, Debug)]
pub struct Position {
    /// Where the attribute is declared.
    pub declared: AttributeRef,
    /// The attribute.
    pub attribute: &'static Attribute,
    /// Whether the entity or a supertype below the declaring one re-declares the attribute as
    /// derived; the record then holds `*`.
    pub derived: bool,
}

/// Orders names by their upper-case form.
fn compare_upper(a: &str, b: &str) -> Ordering {
    a.bytes()
        .map(|c| c.to_ascii_uppercase())
        .cmp(b.bytes().map(|c| c.to_ascii_uppercase()))
}

fn find<T>(items: &[T], name: &str, key: impl Fn(&T) -> &str) -> Option<usize> {
    items
        .binary_search_by(|item| compare_upper(key(item), name))
        .ok()
}

fn index(i: usize) -> Option<u16> {
    u16::try_from(i).ok()
}

impl SchemaTables {
    /// The tables of `schema`, or `None` for another schema or when its generated file is absent.
    #[must_use]
    pub fn of(schema: &Schema) -> Option<&'static Self> {
        match schema {
            #[cfg(arc_ifc_tables_ifc2x3)]
            Schema::Ifc2x3 => Some(&generated::IFC2X3),
            #[cfg(arc_ifc_tables_ifc4)]
            Schema::Ifc4 => Some(&generated::IFC4),
            #[cfg(arc_ifc_tables_ifc4x3)]
            Schema::Ifc4x3 => Some(&generated::IFC4X3),
            _ => None,
        }
    }

    /// Any declaration named `name`, ignoring ASCII case.
    #[must_use]
    pub fn find(&self, name: &str) -> Option<Named> {
        let at = |i| index(i);
        if let Some(i) = find(self.entities, name, |e| e.name) {
            return at(i).map(Named::Entity);
        }
        if let Some(i) = find(self.defined_types, name, |t| t.name) {
            return at(i).map(Named::Defined);
        }
        if let Some(i) = find(self.enumerations, name, |t| t.name) {
            return at(i).map(Named::Enumeration);
        }
        find(self.selects, name, |t| t.name)
            .and_then(at)
            .map(Named::Select)
    }

    /// The index of the entity named `name`, ignoring ASCII case.
    #[must_use]
    pub fn entity_index(&self, name: &str) -> Option<u16> {
        find(self.entities, name, |e| e.name).and_then(index)
    }

    /// The entity named `name`, ignoring ASCII case.
    #[must_use]
    pub fn entity(&self, name: &str) -> Option<&'static Entity> {
        find(self.entities, name, |e| e.name).and_then(|i| self.entities.get(i))
    }

    /// The defined type named `name`, ignoring ASCII case.
    #[must_use]
    pub fn defined_type(&self, name: &str) -> Option<&'static DefinedType> {
        find(self.defined_types, name, |t| t.name).and_then(|i| self.defined_types.get(i))
    }

    /// The enumeration named `name`, ignoring ASCII case.
    #[must_use]
    pub fn enumeration(&self, name: &str) -> Option<&'static Enumeration> {
        find(self.enumerations, name, |t| t.name).and_then(|i| self.enumerations.get(i))
    }

    /// The select type named `name`, ignoring ASCII case.
    #[must_use]
    pub fn select(&self, name: &str) -> Option<&'static Select> {
        find(self.selects, name, |t| t.name).and_then(|i| self.selects.get(i))
    }

    /// The function named `name`, ignoring ASCII case.
    #[must_use]
    pub fn function(&self, name: &str) -> Option<&'static Function> {
        find(self.functions, name, |f| f.name).and_then(|i| self.functions.get(i))
    }

    /// The global rule named `name`, ignoring ASCII case.
    #[must_use]
    pub fn rule(&self, name: &str) -> Option<&'static GlobalRule> {
        find(self.rules, name, |r| r.name).and_then(|i| self.rules.get(i))
    }

    /// The entity and its supertypes, nearest first. The walk stops after as many steps as there
    /// are entities, so a malformed table cannot loop.
    pub fn supertypes(&self, entity: u16) -> impl Iterator<Item = u16> + '_ {
        let mut next = self.entities.get(usize::from(entity)).map(|_| entity);
        let mut steps = 0;
        std::iter::from_fn(move || {
            let current = next?;
            steps += 1;
            next = if steps < self.entities.len() {
                self.entities
                    .get(usize::from(current))
                    .and_then(|e| e.supertype)
            } else {
                None
            };
            Some(current)
        })
    }

    /// Whether `entity` is `ancestor` or one of its subtypes.
    #[must_use]
    pub fn is_subtype_of(&self, entity: u16, ancestor: u16) -> bool {
        self.supertypes(entity).any(|e| e == ancestor)
    }

    /// The positions of a record of `entity`: the explicit attributes of the root supertype first,
    /// each marked derived where the entity or a supertype re-declares it. Empty for an unknown
    /// index.
    #[must_use]
    pub fn positions(&self, entity: u16) -> Vec<Position> {
        let chain: Vec<u16> = self.supertypes(entity).collect();
        let mut positions = Vec::new();
        for &owner in chain.iter().rev() {
            let Some(e) = self.entities.get(usize::from(owner)) else {
                continue;
            };
            for (i, attribute) in e.attributes.iter().enumerate() {
                if let Some(index) = index(i) {
                    positions.push(Position {
                        declared: AttributeRef {
                            entity: owner,
                            index,
                        },
                        attribute,
                        derived: false,
                    });
                }
            }
        }
        for e in chain
            .iter()
            .filter_map(|&i| self.entities.get(usize::from(i)))
        {
            for redeclared in e.derived.iter().filter_map(|d| d.redeclares) {
                for position in &mut positions {
                    position.derived |= position.declared == redeclared;
                }
            }
        }
        positions
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    static ATTRIBUTES: [Attribute; 2] = [
        Attribute {
            name: "Dim",
            ty: TypeRef::Integer,
            optional: false,
        },
        Attribute {
            name: "Tag",
            ty: TypeRef::String {
                width: None,
                fixed: false,
            },
            optional: true,
        },
    ];

    static DERIVED: [Derived; 1] = [Derived {
        name: "Dim",
        redeclares: Some(AttributeRef {
            entity: 0,
            index: 0,
        }),
        ty: TypeRef::Integer,
        source: "3",
        tree: Expr::Integer(3),
    }];

    static TABLES: SchemaTables = SchemaTables {
        name: "T",
        source_blake3: "",
        entities: &[
            Entity {
                name: "IfcBase",
                supertype: None,
                is_abstract: true,
                one_of: &[],
                attributes: &ATTRIBUTES,
                derived: &[],
                inverses: &[],
                unique: &[],
                where_rules: &[],
            },
            Entity {
                name: "IfcLeaf",
                supertype: Some(2),
                is_abstract: false,
                one_of: &[],
                attributes: &[],
                derived: &[],
                inverses: &[],
                unique: &[],
                where_rules: &[],
            },
            Entity {
                name: "IfcMiddle",
                supertype: Some(0),
                is_abstract: false,
                one_of: &[1],
                attributes: &[],
                derived: &DERIVED,
                inverses: &[],
                unique: &[],
                where_rules: &[],
            },
            // A malformed cycle must not hang the walk.
            Entity {
                name: "IfcZCycle",
                supertype: Some(3),
                is_abstract: false,
                one_of: &[],
                attributes: &[],
                derived: &[],
                inverses: &[],
                unique: &[],
                where_rules: &[],
            },
        ],
        defined_types: &[],
        enumerations: &[Enumeration {
            name: "IfcSideEnum",
            items: &["LEFT", "RIGHT"],
        }],
        selects: &[],
        functions: &[],
        rules: &[],
    };

    #[test]
    fn lookups_ignore_case() {
        assert_eq!(TABLES.entity_index("IFCMIDDLE"), Some(2));
        assert_eq!(TABLES.entity_index("ifcleaf"), Some(1));
        assert_eq!(TABLES.entity_index("IfcNone"), None);
        assert_eq!(TABLES.find("IFCSIDEENUM"), Some(Named::Enumeration(0)));
        assert!(
            TABLES
                .enumeration("ifcsideenum")
                .is_some_and(|e| e.contains("left"))
        );
    }

    #[test]
    fn positions_mark_derived_redeclarations() {
        let leaf = TABLES.positions(1);
        let names: Vec<_> = leaf.iter().map(|p| (p.attribute.name, p.derived)).collect();
        assert_eq!(names, [("Dim", true), ("Tag", false)]);
        let base = TABLES.positions(0);
        assert!(base.iter().all(|p| !p.derived));
        assert!(TABLES.positions(99).is_empty());
    }

    #[test]
    fn supertype_walks_are_bounded() {
        assert!(TABLES.is_subtype_of(1, 0));
        assert!(!TABLES.is_subtype_of(0, 1));
        assert_eq!(TABLES.supertypes(3).count(), TABLES.entities.len());
    }

    #[test]
    fn tables_are_absent_for_other_schemas() {
        assert!(SchemaTables::of(&Schema::Other("X".into())).is_none());
    }
}
